import React, { FunctionComponent } from 'react';
import classNames from 'classnames';
import { Field } from 'react-final-form';
import InputValidationMessage from '../../inputValidationMessage';
import LabeledInput from '../../labeledInput';

export type TextInputProps = {
  id?: string;
  label: string;
  name: string;
  className?: string;
  placeholder?: string;
};

const FormTextInput: FunctionComponent<TextInputProps> = ({
  id,
  label,
  name,
  placeholder,
  className,
}) => (
  <Field
    name={name}
    render={({ input, meta }) => (
      <>
        <LabeledInput
          id={id}
          className={classNames(className, meta.error && meta.touched && 'has-error')}
          htmlFor={id}
          label={label}
          active={meta.active || input.value}
          type="text"
          placeholder={placeholder}
          {...input}
        />
        {meta.error && meta.touched && (
          <InputValidationMessage>{meta.error.custom || label + meta.error}</InputValidationMessage>
        )}
      </>
    )}
  />
);

export default FormTextInput;
